Statement stmt(
    db_,
    "SELECT id, pet_id, effect_id, COALESCE(kind, '[]'), COALESCE(args, ''), "
    "COALESCE(tips, ''), COALESCE(come, '') FROM effect_icon"
);
if (!stmt) {
    last_error_ = sqlite3_errmsg(db_);
    return rows;
}

// pet_id 是 JSON 数组字符串（如 "[4911]"），必须解析后精确比对，
// LIKE 匹配会把 14911 误认成 4911。多行（基础/强化/神谕版本）按 icon_id 升序返回。
while (sqlite3_step(stmt.get()) == SQLITE_ROW) {
    const std::vector<int> pet_ids = parse_json_int_array(column_text(stmt.get(), 1));
    if (std::find(pet_ids.begin(), pet_ids.end(), monster_id) == pet_ids.end()) {
        continue;
    }
    SoulMarkDisplayRecord record;
    record.monster_id = monster_id;
    record.icon_id = sqlite3_column_int(stmt.get(), 0);
    record.effect_id = sqlite3_column_int(stmt.get(), 2);
    record.kind_tags = parse_json_int_array(column_text(stmt.get(), 3));
    record.args = parse_int_list(column_text(stmt.get(), 4));
    record.tips = column_text(stmt.get(), 5);
    record.tips_plain = strip_rich_text(record.tips);

// 现代链路：effect_icon.pet_id（JSON 精确匹配）→ tips 全文。
// effect_id 是引擎内部效果号，作为 SoulMark.id（插件程序注册键）。
// 神谕开关（精灵王线 K1，2026-09-24）：神谕波次精灵在 effect_icon 恰有两行版本
//（低 icon = 神谕前、高 icon = 神谕后，官方文本都全），开关选行：
//   未神谕 → **低行**（神谕前文本 + 神谕前程序注册键）
//   已神谕 → **高行**（神谕文本 + 神谕程序注册键，如 3740→2343 / 3516→2411 / 4125→2470）
// 非神谕波次精灵只有一行 → 开关无效果，行为同旧。
const std::vector<official_data::SoulMarkDisplayRecord> displays =
    repository.load_soul_mark_displays_by_monster(monster.id);
if (displays.empty()) {
    return SoulMark{};
}
// 只有"神谕波次精灵（有神谕新技）且确有多版本行"时开关才选行；
// 其余精灵一律取最高版本行（= 旧行为，多版本老精灵不漂移）。
const bool oracle_versions = !monster.oracle_moves.empty() && displays.size() >= 2;
const official_data::SoulMarkDisplayRecord& display =
    (oracle_versions && oracle_on) ? displays.back()
    : (oracle_versions ? displays.front() : displays.back());

// 效果禁用（2026-09-26 禁用基建）：现代链路同样按魂印 id（=效果号）禁用 → 裸壳。
if (std::find(disabled.soul_marks.begin(), disabled.soul_marks.end(),
              display.effect_id) != disabled.soul_marks.end()) {
    return SoulMark(0, "魂印已禁用", "");
}
SoulMark soul_mark(
    display.effect_id,
    monster.name + "魂印" + std::string(oracle_on ? "【神谕】" : ""),
    display.tips_plain,
    EffectArgs(display.args)
);
soul_mark.kind_tags = display.kind_tags;
soul_mark.monster_id = monster.id;
return soul_mark;

// 效果禁用（2026-09-26 禁用基建）：现代链路同样按魂印 id（=效果号）禁用 → 裸壳。
if (std::find(disabled.soul_marks.begin(), disabled.soul_marks.end(),
              display.effect_id) != disabled.soul_marks.end()) {
    return SoulMark(0, "魂印已禁用", "");
}
SoulMark soul_mark(
    display.effect_id,
    monster.name + "魂印" + std::string(oracle_on ? "【神谕】" : ""),
    display.tips_plain,
    EffectArgs(display.args)
);
soul_mark.kind_tags = display.kind_tags;
soul_mark.monster_id = monster.id;
return soul_mark;

rawEffectRecords = record->effects;
// 效果禁用（2026-09-26 禁用基建）：在参数覆盖之前摘除——被禁效果视为不存在，
