async def boss_invalid_effects(self, request):
    """boss 无效效果清单（resources/boss_invalid_effects.json，2026-09-26 禁用基建）。
    来源 = effect_icon.tips 尾注"（boss无效）"解析；前端做徽标 + 一键预填禁用。"""
    import json as _json
    path = os.path.join(REPO_ROOT, "resources", "boss_invalid_effects.json")
    try:
        with open(path, encoding="utf-8") as f:
            return web.json_response(_json.load(f))
    except FileNotFoundError:
        return web.json_response({"count": 0, "ids": [],
                                  "note": "清单未生成（tools 脚本可重建）"})

def move_badge(self, move_row):
    """技能行的效果实现徽标：{status, missing:[effect id], effects:[{id,info,status}]}"""
    effect_ids = _parse_id_array(move_row["side_effect"]) + _parse_id_array(
        move_row["friend_side_effect"]
    )
    if not effect_ids:
        return {"status": "plain", "missing": [], "effects": []}
    effects = []
    missing = []
    statuses = []
    for eid in effect_ids:
        st = self.effect_status(eid, "moves")
        statuses.append(st)
        if st == "none":
            missing.append(eid)
        effects.append({"id": eid, "info": self.effect_info.get(eid, ""), "status": st,
                        "statusLabel": STATUS_LABEL[st]})
